import sys
from functools import lru_cache

n = int(sys.stdin.read().split()[0])

@lru_cache(maxsize=None)
def best(left, screen, buf, sel):
    if left == 0:
        return screen
    r = best(left - 1, screen + 1, buf, False)
    r = max(r, best(left - 1, screen, buf, True))
    if sel:
        r = max(r, best(left - 1, screen, screen, True))
    if buf:
        r = max(r, best(left - 1, screen + buf, buf, False))
    return r

print(best(n, 0, 0, False))

